import { useEffect, useRef, useState } from "react";
import styles from "./Minimap.module.css"
import Slider from "./Slider/Slider";
import MinimapCanvas from "./MinimapCanvas/MinimapCanvas";
import { createChildObserver, createSizeObserver, onNextChat, onPreviousChat } from "./utils";
import { BiLeftArrow, BiRefresh, BiRightArrow,  } from "react-icons/bi";
import { VscLoading } from "react-icons/vsc";
import { CgClose } from "react-icons/cg";
import logo from "../../../../assets/logo.png"

/**
 * Minimap component that provides a visual representation of a larger element's scrollable area.
 * 
 * @param {Object} props - The properties object.
 * @param {string} props.elementSelector - The selector of the HTML element to map to the minimap.
 * 
 * @returns {JSX.Element} The rendered Minimap component.
 * 
 * @component
 * 
 * @remarks
 * This component includes a slider that can be dragged to scroll the mapped element.
 * It also observes changes in the mapped element's children and size to queue redraws.
 * 
 */
const Minimap = (
  {
    elementToMap,
    isFullHtml = false,
  }:
    {
      elementToMap: HTMLElement | null,
      isFullHtml?: boolean
    }
) => {
  const [show, setShow] = useState(true)
  const [mapScale, setMapScale] = useState(1)
  const [sliderHeight, setSliderHeight] = useState(100)
  const [sliderTop, setSliderTop] = useState(0)
  const [canvasLoading, setCanvasLoading] = useState(false)
  const [queueRedraw, setQueueRedraw] = useState(false)
  const minimapRef = useRef<HTMLDivElement>(null);

  const showMinimap = () => setShow(true)
  const hideMinimap = () => setShow(false)

  // Function which handles drag scrolling of the slider.
  function handleSliderDrag(mouseY: number) {
    const minimap = minimapRef.current;
    if (!minimap || !elementToMap) return;
    let viewportHeight = elementToMap.offsetHeight
    if (isFullHtml) {
      viewportHeight = window.innerHeight
    }
    const minimapRect = minimap.getBoundingClientRect();
    const relativeMousePos = mouseY - minimapRect.top;
    const newScrollPos = (relativeMousePos + minimap.scrollTop) / mapScale - 0.5 * viewportHeight;
    elementToMap.scrollTo(
      {
        left: 0,
        top: newScrollPos,
        behavior: "instant",
      }
    );
  }

  function debounce<T extends (...args: any[]) => any>(func: T, timeout = 1000) {
    let timer: ReturnType<typeof setTimeout>;
    return (...args: Parameters<T>) => {
      clearTimeout(timer);
      timer = setTimeout(() => func(...args), timeout);
    };
  }

  const handleQueueRedraw = debounce(() => {
    setQueueRedraw(true)
  })

  useEffect(() => {
    chrome.storage.local.get("minimapOpenState", (result) => {
      if (result.minimapOpenState !== undefined) {
        setShow(result.minimapOpenState);
      }
    });
  }, []);

  useEffect(() => {
    chrome.storage.local.set({ minimapOpenState: show });
  }, [show]);



  // Add observers to look for changes in elementToMap and queue a redraw
  useEffect(() => {
    console.log("Minimap: elementToMap changed to", elementToMap);
    if (!elementToMap) return
    console.log("Minimap: observers attached!")
    const childObserver = createChildObserver(elementToMap, handleQueueRedraw)
    const sizeObserver = createSizeObserver(elementToMap, handleQueueRedraw)
    return () => {
      console.log("Minimap: observers disconnected!")
      childObserver.disconnect();
      sizeObserver.disconnect()
    };
  }, [elementToMap])

  useEffect(() => {
    console.log("Minimap: queueRedraw changed to", queueRedraw);
  }, [queueRedraw])


  // Add event listeners to listen to scroll events of elementToMap
  useEffect(() => {
    if (!elementToMap) return
    const minimap = minimapRef.current;
    if (!minimap) {
      return;
    }

    // Create function which syncs the slider and minimap scroll to the elementToMap's scroll
    const syncScroll = () => {
      const scrollPercentage = elementToMap.scrollTop / elementToMap.scrollHeight;
      const newSliderTop = elementToMap.scrollTop * mapScale;
      setSliderTop(newSliderTop);
      minimap.scrollTop = newSliderTop - (scrollPercentage * (minimap.clientHeight - (mapScale * elementToMap.offsetHeight)))
    };
    const syncMinimapScroll = (event: WheelEvent) => {
      event.preventDefault(); // Prevents default scrolling behavior
      elementToMap.scrollTop += event.deltaY;
    }

    // Add event listenters to the elementToMap and minimap elements to handle scrolling
    //  in both.
    syncScroll()
    if (isFullHtml) {
      window.addEventListener("scroll", syncScroll);
    } else {
      elementToMap.addEventListener("scroll", syncScroll);
    }
    minimap.addEventListener("wheel", syncMinimapScroll);
    return () => {
      if (isFullHtml) {
        window.removeEventListener("scroll", syncScroll);
      } else {
        elementToMap.removeEventListener("scroll", syncScroll);
      }
      minimap.removeEventListener("wheel", syncMinimapScroll)
    };
  }, [canvasLoading, show, elementToMap, isFullHtml, mapScale])

  // Update the sliderHeight when the mapScale and elementToMap is updated
  useEffect(() => {
    if (!elementToMap) return
    if (isFullHtml) {
      setSliderHeight(mapScale * window.innerHeight)
    } else {
      setSliderHeight(mapScale * elementToMap.offsetHeight)
    }
  }, [mapScale, elementToMap, isFullHtml])


  // JSX 
  if (!show) {
    return (
      <div className={styles.hiddenContainer}>
        <button onClick={showMinimap}>
          <img src={logo} />
        </button>
      </div>
    )
  }

  const disableRefresh = queueRedraw || canvasLoading

  return (
    <div
      id="minimap-component"
      className={styles.container}>
      <div
        className={styles.minimapCanvasContainer}
        ref={minimapRef}
      >
        <MinimapCanvas
          queueRedraw={queueRedraw}
          setQueueRedraw={setQueueRedraw}
          elementToMap={elementToMap}
          setMapScale={setMapScale}
          setCanvasLoading={setCanvasLoading}
        />
        {elementToMap && <Slider
          sliderHeight={sliderHeight}
          scrollTop={sliderTop}
          handleDrag={handleSliderDrag}
        />}
      </div>
      <div className={styles.options}>
        <button onClick={hideMinimap}><CgClose /></button>
        {disableRefresh ?
          <button disabled>
            <VscLoading className={styles.spinning} />
          </button> :
          <button onClick={handleQueueRedraw}>
            <BiRefresh />

          </button>
        }

        <button onClick={() => onPreviousChat(false)} >
          <BiLeftArrow />
        </button>
        <button onClick={() => onNextChat(false)} >
          <BiRightArrow />
        </button>
      </div>
    </div>
  );
}

export default Minimap;

import html2canvas from 'html2canvas-pro';
import { Options } from "html2canvas-pro";


/**
 * Returns image of element passed in.
 *
 * @param elementToRender - The element to render as a minimap containing chat messages.
 * @returns A Promise that resolves to void.
 */
export default async function generateMinimapCanvas(
  elementToRender: HTMLElement,
  renderOptions: Partial<Options> = {}
): Promise<HTMLCanvasElement> {

  const rootElement = document.documentElement;
  const rootBackgroundColor = window.getComputedStyle(rootElement).backgroundColor;

  const options: Partial<Options> = {
    ...renderOptions,
    scrollX: 0,
    scrollY: 0,
    scale: 0.25,
    backgroundColor: rootBackgroundColor,
    onclone(document: Document, element: HTMLElement) {
      removeOverflowRestriction(element)
      removeAllImages(document)
      removeChatMargins(element)
    },
  };

  console.log("generateMinimapCanvas: options", options);
  // Generate the canvas
  const canvas = await html2canvas(elementToRender, options);
  console.log("generateMinimapCanvas: canvas generated", canvas);
  return canvas;
}


function removeOverflowRestriction(element: HTMLElement) {
  // Set the element to show its full height
  element.style.height = "auto";
  element.style.overflow = "visible";
}


function removeAllImages(documentClone: Document) {
  documentClone.querySelectorAll("img").forEach(img => {
    const width = img.width;
    const height = img.height;

    // Replace the image with a grey placeholder div
    const greyBox = documentClone.createElement("div");
    greyBox.style.width = `${width}px`;
    greyBox.style.height = `${height}px`;
    greyBox.style.background = "white";
    greyBox.style.display = "inline-block"; // Ensure it doesn't collapse
    greyBox.style.border = "1rem solid red"; // Add red border
    greyBox.style.borderRadius = "10px"; // Add curved corners

    img.replaceWith(greyBox);
  })
}

export function removeChatMargins(element: HTMLElement) {
  let chatWidth = 0;
  element.querySelectorAll(".mx-auto").forEach((k) => {
    const j = k as HTMLElement;
    j.style.marginLeft = "0px";
    j.style.marginRight = "0px";
    if (j.parentElement) {
      j.parentElement.style.paddingRight = "0px";
      j.parentElement.style.paddingLeft = "0px"
    }
    chatWidth = j.offsetWidth;
  });
  element.style.width = `${chatWidth}px`;
  if (chatWidth === 0) {
    element.style.width = "fit-content";
  }
}

